CREATE TABLE `BIZ_PROCESS_MAP` (
  `id` varchar(32) COLLATE utf8mb4_general_ci NOT NULL COMMENT '映射ID',
  `business_key` varchar(100) COLLATE utf8mb4_general_ci NOT NULL COMMENT '业务键（格式：BIZ_TYPE:{id}）',
  `biz_type` varchar(50) COLLATE utf8mb4_general_ci NOT NULL COMMENT '业务类型',
  `biz_id` varchar(100) COLLATE utf8mb4_general_ci NOT NULL COMMENT '业务ID',
  `process_definition_key` varchar(100) COLLATE utf8mb4_general_ci NOT NULL COMMENT '流程定义KEY',
  `process_instance_id` varchar(64) COLLATE utf8mb4_general_ci NOT NULL COMMENT 'Flowable流程实例ID',
  `start_user` varchar(32) COLLATE utf8mb4_general_ci NOT NULL COMMENT '发起人工号',
  `current_assignee` varchar(32) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '当前处理人工号',
  `candidate_groups` text COLLATE utf8mb4_general_ci COMMENT '候选组列表（JSON数组）',
  `process_status` varchar(50) COLLATE utf8mb4_general_ci DEFAULT 'RUNNING' COMMENT '流程状态：RUNNING-运行中, COMPLETED-已完成, CANCELLED-已取消',
  `title` varchar(200) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '流程标题',
  `start_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '发起时间',
  `end_time` datetime DEFAULT NULL COMMENT '结束时间',
  `created_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_business_key` (`business_key`),
  UNIQUE KEY `uk_process_instance` (`process_instance_id`),
  KEY `idx_biz_type_id` (`biz_type`,`biz_id`),
  KEY `idx_start_user` (`start_user`),
  KEY `idx_current_assignee` (`current_assignee`),
  KEY `idx_status` (`process_status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='业务流程映射表';
/*!40101 SET character_set_client = @saved_cs_client */;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `CUST_ALLOC_RELATION` (
  `id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '主键ID',
  `cust_id` varchar(32) COLLATE utf8mb4_general_ci NOT NULL COMMENT '客户ID',
  `cust_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '客户类型 CORP/RETAIL',
  `alloc_dim` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '调整维度：RULE/ACCOUNT',
  `biz_kind` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '业务种类',
  `account_no` varchar(64) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '账号(账号维度必填)',
  `emp_id` varchar(32) COLLATE utf8mb4_general_ci NOT NULL COMMENT '员工工号',
  `fullname` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '员工姓名',
  `dept_no` varchar(60) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '部门编号',
  `dept_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '部门名称',
  `ratio` decimal(5,2) NOT NULL COMMENT '比例(0-100)',
  `effective_date` date NOT NULL COMMENT '生效日期',
  `end_date` date DEFAULT NULL COMMENT '失效日期',
  `source_batch_id` varchar(64) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '来源批次号(可选)',
  `source_process_date` date DEFAULT NULL COMMENT '来源业务日期(可选)',
  `is_original` varchar(2) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '是否是原分配关系,1,是,2,否',
  `created_by` varchar(32) COLLATE utf8mb4_general_ci NOT NULL COMMENT '创建人',
  `created_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_by` varchar(32) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '更新人',
  `updated_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  KEY `idx_cust_id` (`cust_id`),
  KEY `idx_emp_id` (`emp_id`),
  KEY `idx_effective_date` (`effective_date`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='客户业绩分配关系';
/*!40101 SET character_set_client = @saved_cs_client */;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `CUST_CLAIM` (
  `id` varchar(32) COLLATE utf8mb4_general_ci NOT NULL COMMENT '认领ID',
  `cust_id` varchar(32) COLLATE utf8mb4_general_ci NOT NULL COMMENT '客户ID',
  `org_id` varchar(50) COLLATE utf8mb4_general_ci NOT NULL COMMENT '认领机构代码',
  `claimed_by` varchar(32) COLLATE utf8mb4_general_ci NOT NULL COMMENT '认领人工号',
  `maintainer_emp_id` varchar(32) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '维护人工号',
  `claim_status` varchar(50) COLLATE utf8mb4_general_ci DEFAULT 'CLAIMED' COMMENT '认领状态：CLAIMED-已认领, CANCELLED-已取消',
  `claim_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '认领时间',
  `cancel_time` datetime DEFAULT NULL COMMENT '取消时间',
  `cancel_reason` varchar(500) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '取消原因',
  `created_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_cust_org` (`cust_id`,`org_id`),
  KEY `idx_cust_id` (`cust_id`),
  KEY `idx_org_id` (`org_id`),
  KEY `idx_claimed_by` (`claimed_by`),
  KEY `idx_maintainer` (`maintainer_emp_id`),
  KEY `idx_status` (`claim_status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='客户认领关系表';
