CREATE TABLE `PERF_ALLOC_ADJUST_APPLY` (
  `id` varchar(32) COLLATE utf8mb4_general_ci NOT NULL COMMENT '申请ID',
  `apply_no` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '申请编号',
  `cust_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '客户ID',
  `cust_name` varchar(200) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '客户名称（提交时反显快照）',
  `curr_bal` decimal(20,4) DEFAULT NULL COMMENT '当前余额（提交时快照）',
  `m_avg_bal` decimal(20,4) DEFAULT NULL COMMENT '较上日余额（提交时快照）',
  `q_avg_bal` decimal(20,4) DEFAULT NULL COMMENT '年日均余额（提交时快照）',
  `y_avg_bal` decimal(20,4) DEFAULT NULL COMMENT '较上年日均余额（提交时快照）',
  `loan_curr_bal` decimal(20,4) DEFAULT NULL COMMENT '贷款-当前余额快照(MC_005)',
  `loan_m_avg_bal` decimal(20,4) DEFAULT NULL COMMENT '贷款-较上日余额快照(MC_006)',
  `loan_q_avg_bal` decimal(20,4) DEFAULT NULL COMMENT '贷款-年均余额快照(MC_007)',
  `loan_y_avg_bal` decimal(20,4) DEFAULT NULL COMMENT '贷款-较上年均余额快照(MC_008)',
  `cust_type` varchar(20) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '客户类型 CORP/RETAIL',
  `alloc_dim` varchar(16) COLLATE utf8mb4_general_ci NOT NULL COMMENT '维度：RULE/ACCOUNT',
  `biz_kind` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '业务种类',
  `account_no` varchar(64) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '账号(可选)',
  `status` varchar(20) COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'DRAFT' COMMENT '状态：DRAFT/IN_APPROVAL/APPROVED/REJECTED',
  `business_key` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '流程业务键',
  `process_instance_id` varchar(64) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '流程实例ID',
  `owner_org_id` varchar(50) COLLATE utf8mb4_general_ci NOT NULL COMMENT '归属机构',
  `remark` text COLLATE utf8mb4_general_ci COMMENT '备注',
  `created_by` varchar(32) COLLATE utf8mb4_general_ci NOT NULL COMMENT '创建人',
  `created_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_by` varchar(32) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '更新人',
  `updated_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_apply_no` (`apply_no`),
  KEY `idx_cust_id` (`cust_id`),
  KEY `idx_status` (`status`),
  KEY `idx_created_by` (`created_by`),
  KEY `idx_alloc_apply_created_time` (`created_time`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='分配关系调整申请';
/*!40101 SET character_set_client = @saved_cs_client */;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `PERF_ALLOC_ADJUST_ITEM` (
  `id` varchar(32) COLLATE utf8mb4_general_ci NOT NULL COMMENT '项ID',
  `apply_id` varchar(32) COLLATE utf8mb4_general_ci NOT NULL COMMENT '申请ID',
  `acct_no` varchar(64) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '账号(原业绩分配选填)',
  `emp_id` varchar(32) COLLATE utf8mb4_general_ci NOT NULL COMMENT '员工工号',
  `username` varchar(64) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '员工登录名(快照)',
  `emp_chn_name` varchar(64) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '员工中文姓名(快照)',
  `org_code` varchar(32) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '所属部门号(快照)',
  `org_name` varchar(128) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '所属部门名称(快照)',
  `ratio` decimal(5,2) NOT NULL COMMENT '比例(0-100)',
  `remark` varchar(200) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '说明',
  `created_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_apply_emp_kind` (`apply_id`,`emp_id`),
  KEY `idx_apply_id` (`apply_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='分配关系调整明细';
/*!40101 SET character_set_client = @saved_cs_client */;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `PERF_IMPORT_BATCH` (
  `id` varchar(32) COLLATE utf8mb4_general_ci NOT NULL COMMENT '批次ID',
  `batch_no` varchar(64) COLLATE utf8mb4_general_ci NOT NULL COMMENT '批次号',
  `import_type` varchar(20) COLLATE utf8mb4_general_ci NOT NULL COMMENT '导入类型：INDEX_RESULT/KPI_RESULT/TARGET',
  `dim` varchar(20) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '维度：EMP/ORG/CUST；NULL=维度无关导入（METRIC_DEF 等元数据，V1.9 改造）',
  `as_of_date` date DEFAULT NULL COMMENT 'KPI导入基准日(可空)',
  `file_name` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '文件名',
  `file_md5` varchar(64) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '文件MD5',
  `status` varchar(20) COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'CREATED' COMMENT '状态：CREATED/SUCCESS/FAILED',
  `total_rows` int NOT NULL DEFAULT '0' COMMENT '总行数',
  `success_rows` int NOT NULL DEFAULT '0' COMMENT '成功行数',
  `error_rows` int NOT NULL DEFAULT '0' COMMENT '失败行数',
  `updated_rows` int NOT NULL DEFAULT '0' COMMENT '更新行数（V1.11：仅 METRIC_DEF 导入使用，其他类型恒 0）',
  `error_file_object_id` varchar(32) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '错误明细文件ID',
  `remark` varchar(500) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '备注',
  `created_by` varchar(32) COLLATE utf8mb4_general_ci NOT NULL COMMENT '创建人',
  `created_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `SOURCE_OBJECT_KEY` varchar(64) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '导入源文件归档到 OBS 的 fileId',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_batch_no` (`batch_no`),
  KEY `idx_status` (`status`),
  KEY `idx_created_by` (`created_by`),
  KEY `idx_created_time` (`created_time`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='绩效导入批次';
/*!40101 SET character_set_client = @saved_cs_client */;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `PERF_KPI_CALC_LOG` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `data_date` date NOT NULL COMMENT '数据日期',
  `scheme_code` varchar(64) COLLATE utf8mb4_general_ci NOT NULL COMMENT 'KPI方案编码',
  `trigger_type` varchar(10) COLLATE utf8mb4_general_ci NOT NULL COMMENT '触发方式 AUTO自动 / MANUAL手动',
  `trigger_by` varchar(64) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '触发人工号(PT_USER.username)，自动触发为空',
  `start_time` datetime DEFAULT NULL COMMENT '该方案计算开始时间',
  `end_time` datetime DEFAULT NULL COMMENT '该方案计算结束时间',
  `result` varchar(20) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '计算结果 SUCCESS / FAILED',
  `scored_count` int DEFAULT '0' COMMENT '计分对象数',
  `skipped_count` int DEFAULT '0' COMMENT '跳过指标项数',
  `error_msg` text COLLATE utf8mb4_general_ci COMMENT '异常信息',
  `task_id` varchar(32) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '关联 PERF_METRIC_CALC_TASK.id',
  `created_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`),
  KEY `idx_date_scheme` (`data_date`,`scheme_code`),
  KEY `idx_created_time` (`created_time`)
) ENGINE=InnoDB AUTO_INCREMENT=325 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='KPI方案级计算记录';
/*!40101 SET character_set_client = @saved_cs_client */;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
